async function request(path,{method='GET',body,accessToken,op=epoch,schema=''}={}){const allowed=method==='GET'&&(path==='/auth/v1/user'||path.startsWith('/rest/v1/'))||method==='POST'&&['/auth/v1/token?grant_type=password','/auth/v1/token?grant_type=refresh_token','/auth/v1/logout?scope=local','/rest/v1/rpc/martins_empresa_autorizada','/rest/v1/rpc/permitido','/rest/v1/rpc/salvar_registro','/rest/v1/rpc/estado_financeiro'].includes(path);if(!allowed||schema&&schema!=='martins_hml_v1')throw Error('Operação fora do contrato permitido');current(op);const control=new AbortController();controllers.add(control);const timer=setTimeout(()=>control.abort(),timeoutMs);try{const headers={apikey:cfg.key,Accept:'application/json'};if(schema){headers['Accept-Profile']=schema;headers['Content-Profile']=schema;}if(body!==undefined)headers['Content-Type']='application/json';if(accessToken)headers.Authorization='Bearer '+accessToken;const r=await fetcher(cfg.url+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),signal:control.signal,credentials:'omit',cache:'no-store',redirect:'error',referrerPolicy:'no-referrer'});current(op);if(!r.ok){const error=Error('Requisição recusada pelo Supabase (HTTP '+r.status+'). Confira conexão, credenciais, permissões e esquema.');error.status=r.status;if(r.status===401)clear();throw error;}if(r.status===204)return null;const result=await r.json();current(op);return result;}catch(e){if(op!==epoch)throw Error('Operação encerrada ou substituída; resultado descartado');if(e.status)throw e;throw Error(e.name==='AbortError'?'Tempo limite da conexão atingido; nenhuma gravação de dados foi enviada.':'Falha de conexão ou resposta inválida. Confira o projeto e a disponibilidade da rede.');}finally{clearTimeout(timer);controllers.delete(control);}}
