 input=structuredClone(input);if(input.escopo!==undefined&&!['funcionarios','financeiro'].includes(input.escopo))throw Error('Escopo do documento inválido');const financial=input.escopo==='financeiro';input.modulo=financial?'financeiro':'documentos';hmlInput(input);if(!uuid(input.objetoId)||!['pdf','png','jpg'].includes(input.extensao))throw Error('Identificação do arquivo inválida');if(bytes!==undefined&&fileType(bytes)!==input.extensao)throw Error('Extensão não corresponde ao conteúdo');const write=bytes!==undefined,op=epoch;await hmlPermission(input,write,op);
